"use client"

import { useState, useEffect } from "react"
import TabNavigation from "../components/TabNavigation"
import WRFSection from "../components/WRFSection"
import GasesSection from "../components/GasesSection"
import FWISection from "../components/FWISection"
import VientosSection from "../components/VientosSection"
import { fetchEstadisticas } from "../services/api"

const Dashboard = () => {
  const [activeTab, setActiveTab] = useState("WRF")
  const [estadisticas, setEstadisticas] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  useEffect(() => {
    const loadData = async () => {
      setLoading(true)
      setError(null)
      try {
        const data = await fetchEstadisticas()
        setEstadisticas(data)
      } catch (err) {
        setError("Error al cargar las estadísticas")
      } finally {
        setLoading(false)
      }
    }
    loadData()
  }, [])

  const renderActiveSection = () => {
    switch (activeTab) {
      case "WRF":
        return <WRFSection />
      case "FWI":
        return <FWISection />
      case "Gases":
        return <GasesSection />
      case "Vientos":
        return <VientosSection />
      default:
        return <WRFSection />
    }
  }

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="bg-white rounded-lg shadow-sm border border-gray-100 p-6">
          <div className="text-center py-8">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
            <p className="text-gray-600">Cargando dashboard...</p>
          </div>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="space-y-6">
        <div className="bg-white rounded-lg shadow-sm border border-gray-100 p-6">
          <div className="text-center py-8">
            <div className="text-red-600 mb-4">
              <svg className="h-12 w-12 mx-auto" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z" />
              </svg>
            </div>
            <h3 className="text-lg font-semibold text-gray-800 mb-2">{error}</h3>
            <button onClick={() => window.location.reload()} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors">Reintentar</button>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="bg-white rounded-lg shadow-sm border border-gray-100 p-6">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
          <div className="bg-white p-4 rounded-lg border border-gray-200 shadow-sm">
            <h3 className="font-semibold text-blue-800 mb-2">Variables WRF</h3>
            <p className="text-3xl font-bold text-blue-600">{estadisticas?.variables_wrf?.length ?? '-'}</p>
            <p className="text-gray-500 text-sm">Variables meteorológicas</p>
          </div>
          <div className="bg-white p-4 rounded-lg border border-gray-200 shadow-sm">
            <h3 className="font-semibold text-red-800 mb-2">FWI Último Valor</h3>
            <p className="text-3xl font-bold text-red-600">{estadisticas?.fwi_ultimo_valor ?? '-'}</p>
            <p className="text-gray-500 text-sm">Índice de peligro de incendio</p>
          </div>
          <div className="bg-white p-4 rounded-lg border border-gray-200 shadow-sm">
            <h3 className="font-semibold text-green-800 mb-2">Gases Medidos</h3>
            <p className="text-3xl font-bold text-green-600">{estadisticas?.gases_medidos ?? '-'}</p>
            <p className="text-gray-500 text-sm">Tipos de gases atmosféricos</p>
          </div>
          <div className="bg-white p-4 rounded-lg border border-gray-200 shadow-sm">
            <h3 className="font-semibold text-purple-800 mb-2">Vientos en Rutas</h3>
            <p className="text-3xl font-bold text-purple-600">{estadisticas?.vientos_rutas ?? '-'}</p>
            <p className="text-gray-500 text-sm">Alertas de ráfagas</p>
          </div>
        </div>
        <TabNavigation activeTab={activeTab} onTabChange={setActiveTab} estadisticas={estadisticas} />
      </div>
      <div className="bg-white rounded-lg shadow-sm border border-gray-100 p-6 animate-slide-up">
        {renderActiveSection()}
      </div>
    </div>
  )
}

export default Dashboard
